[
  {
    "title": "分支是提交的指標",
    "body": "Git 分支是指向某個提交的可移動指標，建立分支不會複製整個專案。",
    "examples": [
      "main\n└─ A ← B ← C\n             ↑\n          feature"
    ]
  },
  {
    "title": "建立與切換分支",
    "body": "使用分支可在不同開發線之間切換，彼此的提交進度可以分開管理。",
    "examples": [
      "git switch -c feature/login\ngit switch main"
    ]
  },
  {
    "title": "合併分支",
    "body": "合併會把一個分支的提交整合到目前分支；若修改衝突，必須先解決衝突再完成合併。",
    "examples": [
      "git switch main\ngit merge feature/login"
    ]
  }
]
